update public.methods set description = 'Charles Poliquin''s signature hypertrophy protocol: ten sets of ten on one main lift per session at 60% 1RM. Brutal but proven for breaking size plateaus — add load only when all 100 reps are completed cleanly.', defaults = '{"goalTag":"Hypertrophy / volume","intensityColor":"green","setsReps":"10×10","loadPct":"60% 1RM","rest":"60–90s","tempo":"4-0-1-0","notation":"straight","notes":"One main lift per session; add weight when all 10×10 are hit.","durationWeeks":4,"frequencyPerWeek":4,"idealFor":["hypertrophy","work capacity","plateau break"],"contraindications":["total beginners","joint issues — the volume is extreme"],"periodizationPairings":["intensification-block"],"preferredCategories":["pressing","pulling","bilateral_quad","posterior"]}'::jsonb where slug = 'german-volume-training-10x10';

update public.methods set description = 'Antagonistic-pair density training: race the clock in 15–20 minute PR zones, beating your total reps each session. Maximum work in minimum time.', defaults = '{"goalTag":"Density / conditioning","intensityColor":"blue","setsReps":"Antagonistic pairs · AMRAP in 15–20 min","loadPct":"65–75%","rest":"Minimal — race the clock","tempo":"2-0-1-0","notation":"superset","notes":"15–20 min PR zones; increase reps or load next session.","durationWeeks":4,"frequencyPerWeek":3,"idealFor":["fat loss","work capacity","time-poor clients"],"contraindications":["poor cardiovascular base"],"periodizationPairings":["german-body-composition"],"preferredCategories":["pressing","pulling","bilateral_quad","posterior"]}'::jsonb where slug = 'escalating-density-training';

update public.methods set description = 'Neural-charge strength work: descending 3/2/1 rep waves, each wave slightly heavier than the last. Teaches the nervous system to produce more force per attempt.', defaults = '{"goalTag":"Max strength","intensityColor":"red","setsReps":"3/2/1 × 3–4 waves","loadPct":"75–95%","rest":"2–4 min","tempo":"3-0-1-0","notation":"straight","notes":"Each wave slightly heavier than the last.","durationWeeks":3,"frequencyPerWeek":2,"idealFor":["advanced lifters","strength peaking"],"contraindications":["beginners","no recent heavy training"],"periodizationPairings":["accumulation-block"],"preferredCategories":["pressing","pulling","bilateral_quad","posterior"]}'::jsonb where slug = 'wave-loading';

